      "activity_name": "Externalize MSP",
      "activity_description": "Move MSP code into fabric-lib-go and update the main Fabric repository to use the externalized version.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize discovery client",
